{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "RevokeAllSessionsIssuedBeforeTheIncidentCutoff",
      "Effect": "Deny",
      "Action": "*",
      "Resource": "*",
      "Condition": {
        "DateLessThan": { "aws:TokenIssueTime": "2026-08-04T12:00:00Z" }
